package com.wk2.climate.bus

/**
 * A vehicle the app can drive: its canbus id, the vendor profile class that
 * serves it, the vendor's name for it if it has one, and its command table.
 */
data class Vehicle(
    val id: Int,
    val profile: String,
    val vendorName: String?,
    val table: CommandTable,
) {
    val displayName: String get() = vehicleDisplayName(vendorName, profile)
}

/**
 * Every vehicle the app will drive, keyed by canbus id (module 7, read code
 * 1000).
 *
 * Built from `vehicles.tsv`, generated by `tools/extract-vehicles.py` and
 * bundled as a Java resource beside this class. It is plain text rather than
 * JSON so it parses identically on the device and in JVM unit tests, where
 * Android's `org.json` is only a stub.
 *
 * An id not in here is an unknown car: the app draws nothing and sends
 * nothing.
 */
class VehicleCatalog(private val byId: Map<Int, Vehicle>) {

    operator fun get(id: Int): Vehicle? = byId[id]

    val ids: Set<Int> get() = byId.keys

    companion object {

        /**
         * Parses the `vehicles.tsv` format: `#` comments, then
         * `P<TAB>profile<TAB>CONTROL=index,...` and
         * `V<TAB>id<TAB>profile<TAB>vendor const or -<TAB>extra CONTROL=index,... or -`.
         * A `V` line's extras are added to its profile's table for that id only.
         *
         * Anything malformed throws: a catalog that half-loads would quietly
         * turn a supported car into an unknown one.
         */
        fun parse(text: String): VehicleCatalog {
            val profiles = mutableMapOf<String, Map<Command, Int>>()
            val vehicles = mutableMapOf<Int, Vehicle>()
            for (raw in text.lineSequence()) {
                val line = raw.trimEnd('\r')
                if (line.isBlank() || line.startsWith("#")) continue
                val f = line.split('\t')
                when (f[0]) {
                    "P" -> {
                        require(f.size == 3) { "bad P line: $line" }
                        profiles[f[1]] = pairs(f[2])
                    }
                    "V" -> {
                        require(f.size == 5) { "bad V line: $line" }
                        val id = f[1].toInt()
                        val base = requireNotNull(profiles[f[2]]) { "V line names an unknown profile: $line" }
                        val extra = if (f[4] == "-") emptyMap() else pairs(f[4])
                        vehicles[id] = Vehicle(
                            id = id,
                            profile = f[2],
                            vendorName = f[3].takeUnless { it == "-" },
                            table = CommandTable(base + extra + REAR.getOrDefault(f[2], emptyMap())),
                        )
                    }
                    else -> throw IllegalArgumentException("unknown record: $line")
                }
            }
            return VehicleCatalog(vehicles)
        }

        /** The catalog shipped with the app. */
        fun bundled(): VehicleCatalog {
            val stream = requireNotNull(VehicleCatalog::class.java.getResourceAsStream("vehicles.tsv")) {
                "vehicles.tsv is missing from the :bus resources"
            }
            return parse(stream.bufferedReader(Charsets.UTF_8).use { it.readText() })
        }

        /**
         * The rear-zone numbers, per profile.
         *
         * Not in `vehicles.tsv`, because that is generated from `com.syu.air`
         * -- the factory bar -- and the bar has no rear controls. These come
         * from `com.syu.canbus`'s full-screen climate activity, which FYT opens
         * with a REAR tab for exactly the ids of this profile. See
         * `docs/captures/2026-10-28-pa-rear-climate.md`. Whether a given car
         * actually has rear climate is the driver's answer, not ours.
         */
        private val REAR: Map<String, Map<Command, Int>> = mapOf(
            "Car_0374_PA_Jeep_Wrangler" to mapOf(
                Command.REAR_POWER to 16,
                Command.REAR_AUTO to 2,
                Command.REAR_TEMP_UP to 4,
                Command.REAR_TEMP_DOWN to 5,
                Command.REAR_FAN_UP to 6,
                Command.REAR_FAN_DOWN to 7,
                Command.REAR_FACE to 8,
                Command.REAR_FACE_FEET to 9,
                Command.REAR_FEET to 10,
                Command.REAR_LOCK to 32,
            ),
        )

        private fun pairs(spec: String): Map<Command, Int> =
            spec.split(',').associate { pair ->
                val (name, index) = pair.split('=')
                Command.valueOf(name) to index.toInt()
            }
    }
}

/**
 * A readable name from the vendor's constant, e.g. `CAR_PA_GrandCherokee_14_22`
 * -> "Grand Cherokee 2014-2022" (with an en dash).
 *
 * Drops the `CAR_<box>` prefix, splits CamelCase, turns two-digit years into
 * 20xx, and spells out the variant suffixes. Anything else is kept as the
 * vendor wrote it, typos included -- the name has to match what the driver can
 * find in the head unit's own canbus list. No constant: the profile class name.
 */
fun vehicleDisplayName(vendorConst: String?, profile: String): String {
    if (vendorConst == null) return profile
    val tokens = vendorConst.split('_').drop(2)
    val words = mutableListOf<String>()
    val suffixes = mutableListOf<String>()
    var i = 0
    while (i < tokens.size) {
        val t = tokens[i]
        val isYear = t.length == 2 && t.all { it.isDigit() }
        when {
            isYear && i + 1 < tokens.size && tokens[i + 1].let { it.length == 2 && it.all(Char::isDigit) } -> {
                words += "20$t–20${tokens[i + 1]}"
                i++
            }
            isYear -> words += "20$t"
            t in SUFFIXES -> suffixes += SUFFIXES.getValue(t)
            else -> words += t.replace(CAMEL, " ")
        }
        i++
    }
    return (listOf(words.joinToString(" ")) + suffixes).joinToString(", ")
}

private val SUFFIXES = mapOf("Amp" to "amplified audio", "CD" to "CD", "H" to "high trim", "Low" to "low trim")

private val CAMEL = Regex("(?<=[a-z])(?=[A-Z])")
